CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,role TEXT NOT NULL,totp TEXT NOT NULL DEFAULT '');
 CREATE TABLE IF NOT EXISTS login_sessions(hash TEXT PRIMARY KEY,user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,expires_at BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS objects(kind TEXT NOT NULL,id TEXT NOT NULL,payload TEXT NOT NULL,updated_at BIGINT NOT NULL,PRIMARY KEY(kind,id));
 CREATE TABLE IF NOT EXISTS settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
 INSERT INTO settings VALUES('version','1') ON CONFLICT DO NOTHING;
 CREATE TABLE IF NOT EXISTS traffic_daily(date TEXT NOT NULL,route_id TEXT NOT NULL,ingress_bytes BIGINT NOT NULL DEFAULT 0,egress_bytes BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(date,route_id));
 CREATE TABLE IF NOT EXISTS audit_logs(id BIGSERIAL PRIMARY KEY,actor_id TEXT NOT NULL,action TEXT NOT NULL,target TEXT NOT NULL,created_at BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS stream_sessions(id TEXT PRIMARY KEY,route_id TEXT NOT NULL,started_at BIGINT NOT NULL,ended_at BIGINT,bytes_sent BIGINT NOT NULL DEFAULT 0,status TEXT NOT NULL);
 CREATE TABLE IF NOT EXISTS quota_leases(date TEXT NOT NULL,route_id TEXT NOT NULL,node_id TEXT NOT NULL,granted BIGINT NOT NULL,reported BIGINT NOT NULL DEFAULT 0,PRIMARY KEY(date,route_id,node_id));
 CREATE TABLE IF NOT EXISTS remote_sessions(node_id TEXT NOT NULL,id TEXT NOT NULL,payload TEXT NOT NULL,updated_at BIGINT NOT NULL,PRIMARY KEY(node_id,id));
 CREATE TABLE IF NOT EXISTS enroll_tokens(hash TEXT PRIMARY KEY,expires_at BIGINT NOT NULL);
 CREATE TABLE IF NOT EXISTS nonces(node_id TEXT NOT NULL,nonce TEXT NOT NULL,created_at BIGINT NOT NULL,PRIMARY KEY(node_id,nonce));
 CREATE TABLE IF NOT EXISTS relay_reports(node_id TEXT NOT NULL,report_id TEXT NOT NULL,created_at BIGINT NOT NULL,PRIMARY KEY(node_id,report_id));
